-- Plant designer: a kit item that opens an editor for flowers (stem, leaves,
-- head shape, petal/centre colours) and L-system trees (axiom, rules,
-- angle, iterations, bark, foliage, blossom, fruit). Right-click the ground
-- to grow the current design, save designs by name, or hand out seed packets
-- that carry a design in their item metadata.
--
-- Every node is a [multiply tint of a handful of greyscale 16x16 tiles
-- (generated by util/content/generate_luanti_web_flora.py), so 84 plant
-- nodes cost six textures.

local MP = core.get_modpath("lw_flora")
dofile(MP .. DIR_DELIM .. "logic.lua")
local L = lw_flora.logic
local F = core.formspec_escape
local storage = core.get_mod_storage()

local FORMNAME = "lw_flora:designer"
local META_CURRENT = "lw_flora:current"

local HEX = {}
for _, c in ipairs(lw_nodes.wool_colors) do
	HEX[c.name] = c.hex
	assert(L.COLOR_SET[c.name], "lw_flora colour list out of sync: " .. c.name)
end
local DESC = {}
for _, c in ipairs(lw_nodes.wool_colors) do
	DESC[c.name] = c.desc
end

local BARK = {
	oak = {desc = "Oak", hex = "#7b5230"},
	birch = {desc = "Birch", hex = "#e4e0d4"},
	dark = {desc = "Dark", hex = "#3e2b1e"},
	palm = {desc = "Palm", hex = "#c8a97a"},
}

local function tint(tex, hex)
	return tex .. "^[multiply:" .. hex
end

