-- Nodes
--------------------------------------------------------------------------

local SOFT = {snappy = 3, oddly_breakable_by_hand = 3, lw_flora = 1}

local function groups(extra)
	local g = {}
	for k, v in pairs(SOFT) do g[k] = v end
	for k, v in pairs(extra or {}) do g[k] = v end
	return g
end

