--------------------------------------------------------------------------
-- Design state
--------------------------------------------------------------------------

local function current(player)
	local raw = player:get_meta():get_string(META_CURRENT)
	local d = raw ~= "" and core.parse_json(raw) or nil
	local clean = L.sanitize(d or L.default_design("flower"))
	return clean
end

local function set_current(player, d)
	local clean = L.sanitize(d)
	player:get_meta():set_string(META_CURRENT, core.write_json(clean))
	return clean
end

local function saved(name)
	local raw = storage:get_string("designs:" .. name)
	local list = raw ~= "" and core.parse_json(raw) or nil
	return type(list) == "table" and list or {}
end

local function set_saved(name, list)
	storage:set_string("designs:" .. name, core.write_json(list))
end

-- Per-player transient UI state: selected saved row, last status line.
local ui = {}
local function state(name)
	ui[name] = ui[name] or {sel = 0, status = ""}
	return ui[name]
end

--------------------------------------------------------------------------
-- Growing
--------------------------------------------------------------------------

local function can_fill(pos, owner)
	local node = core.get_node_or_nil(pos)
	if not node then
		return false
	end
	if node.name ~= "air" then
		local def = core.registered_nodes[node.name]
		if not (def and def.buildable_to) then
			return false
		end
	end
	return not core.is_protected(pos, owner)
end

-- Returns ok, message.
function lw_flora.grow(pos, design, owner)
	local d, problems = L.sanitize(design)
	if #problems > 0 then
		return false, problems[1]
	end
	owner = owner or ""
	if core.is_protected(pos, owner) then
		return false, "That spot is protected"
	end
	if d.kind == "flower" then
		local placed = 0
		for _, part in ipairs(L.flower_layout(d)) do
			local p = {x = pos.x + part.x, y = pos.y + part.y, z = pos.z + part.z}
			if can_fill(p, owner) then
				core.set_node(p, {name = part.node})
				placed = placed + 1
			end
		end
		return placed > 0, ("Grew %s (%d blocks)"):format(d.name, placed)
	end
	local ok, err = pcall(core.spawn_tree, pos, L.tree_def(d, math.random(1, 2^30)))
	if not ok then
		return false, "Tree failed: " .. tostring(err)
	end
	return true, "Grew " .. d.name
end

--------------------------------------------------------------------------
-- Editor formspec
--------------------------------------------------------------------------

local function dropdown(x, y, w, field, options, value, labels)
	local idx = 1
	local shown = {}
	for i, opt in ipairs(options) do
		if opt == value then idx = i end
		shown[i] = F(labels and labels[opt] or opt)
	end
	return ("dropdown[%s,%s;%s,0.7;%s;%s;%d;false]"):format(
		x, y, w, field, table.concat(shown, ","), idx)
end

local function preset_names(list)
	local out = {F("(choose a preset)")}
	for _, p in ipairs(list) do out[#out + 1] = F(p.name) end
	return table.concat(out, ",")
end

local function swatch(x, y, color)
	return ("box[%s,%s;0.5,0.7;%s]"):format(x, y, HEX[color] or "#000000")
end

local function formspec(player)
	local name = player:get_player_name()
	local d = current(player)
	local st = state(name)
	local _, problems = L.sanitize(d)
	local tab = d.kind == "tree" and 2 or 1
	local fs = {
		"formspec_version[4]",
		"size[15,11]",
		"tabheader[0,0;lw_tab;", F("Flower"), ",", F("Tree"), ";", tab, ";false;true]",
		"label[0.4,0.5;", F("Plant Designer — right-click the ground with the designer to grow"), "]",
		"field[0.4,1.2;5,0.7;lw_name;", F("Name"), ";", F(d.name), "]",
		"field_close_on_enter[lw_name;false]",
	}
	local function add(...)
		for _, s in ipairs({...}) do fs[#fs + 1] = s end
	end

	if d.kind == "flower" then
		add("label[0.4,2.3;", F("Preset"), "]",
			"dropdown[2.2,2;3.2,0.7;lw_fpreset;", preset_names(L.FLOWER_PRESETS), ";1;true]",
			"label[0.4,3.3;", F("Head shape"), "]",
			dropdown(2.2, 3, 3.2, "lw_head", L.HEADS, d.head),
			"label[0.4,4.3;", F("Stem height"), "]",
			"scrollbaroptions[min=1;max=", L.MAX_STEM, ";smallstep=1;largestep=1]",
			"scrollbar[2.2,4.05;2.6,0.5;horizontal;lw_stem;", d.stem, "]",
			"label[5,4.3;", d.stem, "]",
			"label[0.4,5.3;", F("Leaves"), "]",
			"scrollbaroptions[min=0;max=", L.MAX_STEM - 1, ";smallstep=1;largestep=1]",
			"scrollbar[2.2,5.05;2.6,0.5;horizontal;lw_leaves;", d.leaves, "]",
			"label[5,5.3;", d.leaves, "]",
			"label[0.4,6.3;", F("Petals"), "]",
			dropdown(2.2, 6, 2.6, "lw_petal", L.COLORS, d.petal, DESC), swatch(4.9, 6, d.petal),
			"label[0.4,7.3;", F("Centre"), "]",
			dropdown(2.2, 7, 2.6, "lw_center", L.COLORS, d.center, DESC), swatch(4.9, 7, d.center),
			"label[0.4,8.3;", F("Foliage"), "]",
			dropdown(2.2, 8, 2.6, "lw_foliage", L.COLORS, d.foliage, DESC), swatch(4.9, 8, d.foliage))
	else
		add("label[0.4,2.3;", F("Preset"), "]",
			"dropdown[2.2,2;3.2,0.7;lw_tpreset;", preset_names(L.TREE_PRESETS), ";1;true]",
			"field[0.4,3.3;9,0.7;lw_axiom;", F("Axiom"), ";", F(d.axiom), "]",
			"field[0.4,4.5;9,0.7;lw_rules_a;", F("Rule A"), ";", F(d.rules_a), "]",
			"field[0.4,5.7;9,0.7;lw_rules_b;", F("Rule B"), ";", F(d.rules_b), "]",
			"field_close_on_enter[lw_axiom;false]",
			"field_close_on_enter[lw_rules_a;false]",
			"field_close_on_enter[lw_rules_b;false]",
			"field[0.4,6.9;1.6,0.7;lw_angle;", F("Angle"), ";", d.angle, "]",
			"field[2.2,6.9;1.6,0.7;lw_iter;", F("Iterations"), ";", d.iterations, "]",
			"field[4.0,6.9;1.6,0.7;lw_random;", F("Randomness"), ";", d.random_level, "]",
			"label[5.9,6.7;", F("Trunk"), "]",
			dropdown(5.9, 6.9, 1.9, "lw_trunk", L.TRUNK_TYPES, d.trunk_type),
			"checkbox[8,7.25;lw_thin;", F("Thin"), ";", tostring(d.thin), "]",
			"label[0.4,8.2;", F("Bark"), "]",
			dropdown(1.6, 7.9, 2, "lw_bark", L.BARKS, d.bark),
			"label[3.8,8.2;", F("Foliage"), "]",
			dropdown(5, 7.9, 2.4, "lw_foliage", L.COLORS, d.foliage, DESC), swatch(7.5, 7.9, d.foliage),
			"label[0.4,9.2;", F("Blossom"), "]",
			dropdown(1.6, 8.9, 2.4, "lw_blossom", L.COLORS, d.blossom, DESC), swatch(4.1, 8.9, d.blossom),
			"field[4.7,8.9;0.9,0.7;lw_bchance;;", d.blossom_chance, "]",
			"label[5.65,9.2;%]",
			"label[6.1,9.2;", F("Fruit"), "]",
			dropdown(7.0, 8.9, 2.2, "lw_fruit", L.COLORS, d.fruit, DESC),
			"field[9.3,8.9;0.9,0.7;lw_fchance;;", d.fruit_chance, "]",
			"label[10.25,9.2;%]",
			"label[9.7,3.0;", F("Symbols: F branch  T trunk  f leaves  R fruit  G skip"), "]",
			"label[9.7,3.4;", F("+ - yaw   & ^ pitch   / * roll   [ ] push/pop"), "]",
			"label[9.7,3.8;", F("A B expand rules (a b: 90%/80% chance)"), "]")
	end

	-- Saved designs column.
	local list = saved(name)
	local rows = {}
	for i, s in ipairs(list) do
		rows[i] = F((s.kind == "tree" and "[T] " or "[F] ") .. s.name)
	end
	add("label[9.7,0.5;", F("Saved designs"), "]")
	if d.kind == "flower" then
		add("textlist[9.7,0.8;4.9,4.6;lw_saved;", table.concat(rows, ","), ";", st.sel, ";false]")
	else
		add("textlist[11.2,4.3;3.4,3.1;lw_saved;", table.concat(rows, ","), ";", st.sel, ";false]")
	end
	add("button[9.7,", d.kind == "flower" and "5.6" or "1.0", ";1.6,0.7;lw_save;", F("Save"), "]",
		"button[11.4,", d.kind == "flower" and "5.6" or "1.0", ";1.6,0.7;lw_load;", F("Load"), "]",
		"button[13.1,", d.kind == "flower" and "5.6" or "1.0", ";1.5,0.7;lw_delete;", F("Delete"), "]",
		"button[9.7,", d.kind == "flower" and "6.5" or "1.9", ";2.4,0.7;lw_seeds;", F("Make 8 seeds"), "]",
		"button[12.2,", d.kind == "flower" and "6.5" or "1.9", ";2.4,0.7;lw_apply;", F("Apply"), "]")

	local status = st.status
	if #problems > 0 then
		status = problems[1]
	end
	add("label[0.4,10.3;", F(status), "]",
		"button_exit[12.6,10;2,0.7;lw_close;", F("Done"), "]")
	return table.concat(fs)
end

local function show(player)
	core.show_formspec(player:get_player_name(), FORMNAME, formspec(player))
end
lw_flora.show_designer = show

local function scroll_value(raw)
	local e = raw and core.explode_scrollbar_event(raw)
	return e and e.value
end

-- Pull every editable field the client sent into the design.
local function read_fields(d, fields)
	if fields.lw_name then d.name = fields.lw_name end
	if d.kind == "flower" then
		d.head = fields.lw_head or d.head
		d.stem = scroll_value(fields.lw_stem) or d.stem
		d.leaves = scroll_value(fields.lw_leaves) or d.leaves
		d.petal = fields.lw_petal and fields.lw_petal:lower():gsub(" ", "_") or d.petal
		d.center = fields.lw_center and fields.lw_center:lower():gsub(" ", "_") or d.center
		d.foliage = fields.lw_foliage and fields.lw_foliage:lower():gsub(" ", "_") or d.foliage
	else
		d.axiom = fields.lw_axiom or d.axiom
		d.rules_a = fields.lw_rules_a or d.rules_a
		d.rules_b = fields.lw_rules_b or d.rules_b
		d.angle = fields.lw_angle or d.angle
		d.iterations = fields.lw_iter or d.iterations
		d.random_level = fields.lw_random or d.random_level
		d.trunk_type = fields.lw_trunk or d.trunk_type
		if fields.lw_thin then d.thin = fields.lw_thin == "true" end
		d.bark = fields.lw_bark or d.bark
		d.foliage = fields.lw_foliage and fields.lw_foliage:lower():gsub(" ", "_") or d.foliage
		d.blossom = fields.lw_blossom and fields.lw_blossom:lower():gsub(" ", "_") or d.blossom
		d.fruit = fields.lw_fruit and fields.lw_fruit:lower():gsub(" ", "_") or d.fruit
		d.blossom_chance = fields.lw_bchance or d.blossom_chance
		d.fruit_chance = fields.lw_fchance or d.fruit_chance
	end
	return d
end

local function give_seeds(player, d)
	local stack = ItemStack("lw_flora:seed 8")
	local meta = stack:get_meta()
	meta:set_string("design", core.write_json(d))
	meta:set_string("description", ("Seed: %s\n%s"):format(d.name,
		d.kind == "tree" and "Plant to grow this tree" or "Plant to grow this flower"))
	local left = player:get_inventory():add_item("main", stack)
	return left:is_empty()
end

core.register_on_player_receive_fields(function(player, formname, fields)
	if formname ~= FORMNAME then
		return
	end
	local name = player:get_player_name()
	local st = state(name)
	local d = read_fields(current(player), fields)
	st.status = ""

	-- Preset dropdowns use index events; entry 1 is the "(choose)" row, and
	-- the redraw resets it, so any other index is a fresh pick.
	local pidx = tonumber(d.kind == "flower" and fields.lw_fpreset or fields.lw_tpreset)
	local plist = d.kind == "flower" and L.FLOWER_PRESETS or L.TREE_PRESETS
	if pidx and pidx > 1 and plist[pidx - 1] then
		local kind = d.kind
		d = L.copy(plist[pidx - 1])
		d.kind = kind
		st.status = "Preset: " .. d.name
	end

	if fields.lw_tab then
		local kind = fields.lw_tab == "2" and "tree" or "flower"
		if kind ~= d.kind then
			d = L.default_design(kind)
		end
	end

	if fields.lw_saved then
		local e = core.explode_textlist_event(fields.lw_saved)
		if e.type == "CHG" or e.type == "DCL" then
			st.sel = e.index
		end
		if e.type == "DCL" then
			fields.lw_load = true
		end
	end

	local list = saved(name)
	if fields.lw_save then
		local clean, problems = L.sanitize(d)
		if #problems == 0 then
			list = L.upsert(list, clean)
			set_saved(name, list)
			st.sel = 1
			st.status = "Saved " .. clean.name
		end
	elseif fields.lw_load then
		local pick = list[st.sel]
		if pick then
			d = L.copy(pick)
			st.status = "Loaded " .. tostring(pick.name)
		end
	elseif fields.lw_delete then
		if list[st.sel] then
			st.status = "Deleted " .. tostring(list[st.sel].name)
			set_saved(name, L.remove(list, st.sel))
			st.sel = 0
		end
	elseif fields.lw_seeds then
		local clean, problems = L.sanitize(d)
		if #problems == 0 then
			st.status = give_seeds(player, clean) and "8 seed packets added"
				or "Inventory full"
		end
	elseif fields.lw_apply then
		st.status = "Design ready — right-click the ground to grow it"
	end

	set_current(player, d)
	if fields.quit or fields.lw_close then
		return true
	end
	show(player)
	return true
end)

core.register_on_leaveplayer(function(player)
	ui[player:get_player_name()] = nil
end)

--------------------------------------------------------------------------
-- Items
--------------------------------------------------------------------------

local function grow_at_pointed(player, pointed, design)
	if not pointed or pointed.type ~= "node" then
		return false
	end
	local name = player:get_player_name()
	local under = core.get_node(pointed.under)
	local udef = core.registered_nodes[under.name]
	local pos = (udef and udef.buildable_to) and pointed.under or pointed.above
	local ok, msg = lw_flora.grow(pos, design, name)
	if msg then
		core.chat_send_player(name, msg)
	end
	return ok
end

core.register_craftitem("lw_flora:designer", {
	description = "Plant Designer\nPunch: open editor\nPlace: grow current design",
	inventory_image = "lw_flora_designer.png",
	stack_max = 1,
	range = 10,
	on_use = function(itemstack, user)
		if user and user:is_player() then
			show(user)
		end
		return itemstack
	end,
	on_secondary_use = function(itemstack, user)
		if user and user:is_player() then
			show(user)
		end
		return itemstack
	end,
	on_place = function(itemstack, placer, pointed)
		if placer and placer:is_player() then
			-- Let nodes with their own right-click (buttons, remotes) win.
			local node = core.get_node(pointed.under)
			local ndef = core.registered_nodes[node.name]
			if ndef and ndef.on_rightclick and not placer:get_player_control().sneak then
				return ndef.on_rightclick(pointed.under, node, placer, itemstack, pointed)
			end
			grow_at_pointed(placer, pointed, current(placer))
		end
		return itemstack
	end,
})

core.register_craftitem("lw_flora:seed", {
	description = "Seed Packet",
	inventory_image = "lw_flora_seed.png",
	groups = {not_in_creative_inventory = 1},
	on_place = function(itemstack, placer, pointed)
		if not (placer and placer:is_player()) then
			return itemstack
		end
		local raw = itemstack:get_meta():get_string("design")
		local design = raw ~= "" and core.parse_json(raw) or nil
		if not design then
			core.chat_send_player(placer:get_player_name(), "This packet is empty")
			return itemstack
		end
		if grow_at_pointed(placer, pointed, design) then
			itemstack:take_item()
		end
		return itemstack
	end,
})

core.register_chatcommand("plants", {
	description = "Open the plant designer",
	func = function(name)
		local player = core.get_player_by_name(name)
		if not player then
			return false, "Not in game"
		end
		show(player)
		return true
	end,
})
